script:
var doc = Document;
// Goal: add a project-wide shared parameter, "Fire Rating Note", to every wall and door so
// schedules and tags can show it. Shared parameters live in a text file Revit reads; the API
// cannot create that file, only open one.
var app = UIApplication.Application;
// A blank project has levels already; take the lowest one rather than creating another.
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (level == null || l.Elevation < level.Elevation) level = l;
}

// 1. Write the shared-parameter file. There is NO Application.CreateSharedParameterFile: the
//    format is plain tab-delimited text (META, GROUP and PARAM rows) and System.IO writes it.
//    Keep it under the connector's exports directory so no user path is touched, with a unique
//    name so reruns cannot collide. The GUID is the parameter's permanent identity across projects.
string paramName = "Fire Rating Note";
string groupName = "Connector";
string guid = System.Guid.NewGuid().ToString();
string filePath = System.IO.Path.Combine(Connector.ExportsDirectory, "shared-parameters-" + System.Guid.NewGuid().ToString("N") + ".txt");
string content = "# This is a Revit shared parameter file.\n# Do not edit manually.\n"
  + "*META\tVERSION\tMINVERSION\nMETA\t2\t1\n"
  + "*GROUP\tID\tNAME\nGROUP\t1\t" + groupName + "\n"
  + "*PARAM\tGUID\tNAME\tDATATYPE\tDATACATEGORY\tGROUP\tVISIBLE\tDESCRIPTION\tUSERMODIFIABLE\n"
  + "PARAM\t" + guid + "\t" + paramName + "\tTEXT\t\t1\t1\t\t1\n";
System.IO.File.WriteAllText(filePath, content);

// 2. Point the application at the file and open it. SharedParametersFilename is a process-wide
//    Revit setting: remember the previous value and restore it in a finally, and delete the
//    temporary file, so the session is left as found even if a later step throws.
string previousFile = app.SharedParametersFilename;
try {
  app.SharedParametersFilename = filePath;
  var defFile = app.OpenSharedParameterFile();
  if (defFile == null) throw new System.Exception("OpenSharedParameterFile returned null; the file is not a valid shared-parameter file");
  var definition = defFile.Groups.get_Item(groupName).Definitions.get_Item(paramName) as Autodesk.Revit.DB.ExternalDefinition;
  if (definition == null) throw new System.Exception("definition not found in the shared-parameter file");

  return Connector.WithTransaction(doc, () => {
    // 3. Bind the definition to categories. A CategorySet names which categories carry the
    //    parameter; an InstanceBinding puts it on instances (TypeBinding would put it on types).
    var categories = app.Create.NewCategorySet();
    categories.Insert(doc.Settings.Categories.get_Item(Autodesk.Revit.DB.BuiltInCategory.OST_Walls));
    categories.Insert(doc.Settings.Categories.get_Item(Autodesk.Revit.DB.BuiltInCategory.OST_Doors));
    var binding = app.Create.NewInstanceBinding(categories);
    // 4. The third argument is the parameter group shown in the Properties palette. In Revit 2025+
    //    it is a ForgeTypeId from GroupTypeId (Data, IdentityData, Text, ...); the old
    //    BuiltInParameterGroup enum no longer exists.
    bool bound = doc.ParameterBindings.Insert(definition, binding, Autodesk.Revit.DB.GroupTypeId.Data);
    if (!bound) throw new System.Exception("ParameterBindings.Insert returned false (already bound?)");

    // 5. Verify on a real element: a new wall now has the parameter and accepts a value.
    var wall = Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(
        new Autodesk.Revit.DB.XYZ(0, 0, level.Elevation), new Autodesk.Revit.DB.XYZ(10, 0, level.Elevation)), level.Id, false);
    doc.Regenerate();
    var p = wall.LookupParameter(paramName);
    bool present = p != null && p.IsShared;
    if (present && !p.IsReadOnly) p.Set("2 HR");
    string readBack = present ? wall.LookupParameter(paramName).AsString() : null;

    return new { bound, parameter = paramName, guid, present, readBack, wallId = wall.Id.Value, groupShown = "Data" };
  });
} finally {
  app.SharedParametersFilename = previousFile;
  try { System.IO.File.Delete(filePath); } catch { }
}
